let html = "";
if ($input.item && $input.item.json) {
  if ($input.item.json.data) {
    html = $input.item.json.data;
  } else if ($input.item.json.html) {
    html = $input.item.json.html;
  }
}

if (html.length === 0) {
  return [{ json: { error: "NO_JOBS_FOUND", message: "HTML data is empty." } }];
}

let jobs = [];
let parts = html.split('result-list-narrow-item-wrapper');

// Loop through chunks after the wrapper keyword
for (let i = 1; i < parts.length; i++) {
  let chunk = parts[i];
  let title = "";

  // Find a title marker
  let pos = chunk.indexOf('title');
  if (pos !== -1) {
    let sub = chunk.substring(pos);
    let startTag = sub.indexOf('>');
    let endTag = sub.indexOf('</');
    if (startTag !== -1 && endTag !== -1 && endTag > startTag) {
      title = sub.substring(startTag + 1, endTag).trim();
      // Clean any leftover inner tags
      title = title.replace(/<[^>]*>?/gm, '');
    }
  }

  if (title.length > 0) {
    jobs.push({ json: { title: title } });
  }
}

if (jobs.length === 0) {
  return [{ json: { error: "NO_JOBS_FOUND", message: "No jobs parsed from chunks." } }];
}

return jobs;

