  }
}

if (html.length === 0) {
  return [{ json: { error: "NO_JOBS_FOUND", message: "HTML data is empty." } }];
}

let jobs = [];
let parts = html.split('result-list-narrow-item-wrapper');

for (let i = 1; i < parts.length; i++) {
  let chunk = parts[i];
  let title = "";
  let link = "";

  // Extract Title
  let pos = chunk.indexOf('title');
  if (pos !== -1) {
    let sub = chunk.substring(pos);
    let startTag = sub.indexOf('>');
    let endTag = sub.indexOf('</');
    if (startTag !== -1 && endTag !== -1 && endTag > startTag) {
      title = sub.substring(startTag + 1, endTag);
      // Remove HTML tags and normalize whitespace/newlines
      title = title.replace(/<[^>]*>?/gm, '').replace(/\s+/g, ' ').trim();
    }
  }

  // Extract URL/Link
  let hrefPos = chunk.indexOf('href="');
  if (hrefPos !== -1) {
    let subHref = chunk.substring(hrefPos + 6);
    let endQuote = subHref.indexOf('"');
    if (endQuote !== -1) {
      let rawLink = subHref.substring(0, endQuote);
      link = rawLink.startsWith('http') ? rawLink : `https://www.xe.gr${rawLink}`;
    }
  }

  if (title.length > 0) {
    jobs.push({ json: { title: title, url: link } });
  }
}

if (jobs.length === 0) {
  return [{ json: { error: "NO_JOBS_FOUND", message: "No jobs parsed from chunks." } }];
}

return jobs;

